RV('C1-L138','Unit 8 review',
 goal='eu consigo recuperar e usar, em contextos novos, o que aprendi na Unidade 8 do C1: subjuntivo, resenha crítica, account for e condicionais mistas.',
 read=('Reading · A short analysis',text('Analysis: What Accounts for the Delay?',['The project is two years late. Managers **account for** the delay in three ways: staffing, weather and a change of design. **If they had hired** more engineers earlier, **the bridge would be** open now. **It is essential that** the new schedule **be** published. **Were the team** larger, the work **would have finished** sooner. **On balance**, the report is fair, although it fails to **account for** the cost of waiting.'],kicker='ANALYSIS',by='Infrastructure Desk',gloss=[('delay','atraso'),('staffing','pessoal'),('design','projeto'),('schedule','cronograma')])),
 tf=[('The project is early.','F','two years late.'),('The report accounts for the cost of waiting.','F','fails to account for.'),('Managers give three explanations.','T','three ways.')],
 mc=[('“delay” = ?',['atraso','demora só','dilema'],0,'delay = atraso.'),('“schedule” = ?',['cronograma','esquema','escudo'],0,'schedule = cronograma.')],
 recap=[table(['Tópico','Lembrete'],[['Subjunctive','**It is essential that the schedule be published.**'],['Critical review','**On balance…, although…**'],['account for','**accounts for** half / **failed to account for**'],['Mixed conditionals','**If they had hired…, the bridge would be open now.**'],['scale back','**scale back** the plan']],'Unidade 8: o que lembrar')],
 dlg=('Review chat',[('Ana','How do managers account for the delay?','Como os gerentes explicam o atraso?'),('Leo','Staffing, weather and a design change.','Pessoal, clima e mudança de projeto.'),('Ana','What would have happened with more engineers?','O que teria acontecido com mais engenheiros?'),('Leo','If they had hired more, the bridge would be open now.','Se tivessem contratado mais, a ponte estaria aberta agora.')]),
 speak_=[('Use a mixed conditional.','Use.','If I had slept more, I would feel better now.'),('Use account for.','Use.','Rent accounts for half my budget.'),('Use a subjunctive.','Use.','I suggest that the plan be published.')],
 wr=('Write a 6-sentence critical analysis of a delayed project using two structures from the unit.','The tunnel project is a year late. Managers account for the delay by citing weather and staffing. If they had hired earlier, the tunnel would be open now. I recommend that the new schedule be published. On balance, the explanation is plausible, although it fails to account for design changes. They should scale back the next phase.',['Usei **condicional mista**','Usei **account for**','Usei **recommend that**'],'6 frases'),
 teach=['Reveja a ligação tempo da condição × tempo do resultado.','Peça frases com account for nos três sentidos.','Pratique o subjuntivo oralmente.'],exam_extra=['No IELTS Writing, condicionais corretas e variadas elevam a pontuação de gramática.'])
